"""Pack the three integers of one telemetry line."""
def pack(a, b, c):
    return a.to_bytes(3, 'big') + b.to_bytes(3, 'big') + c.to_bytes(4, 'big')

def unpack(data, p):
    a = int.from_bytes(data[p:p+3], 'big')
    b = int.from_bytes(data[p+3:p+6], 'big')
    c = int.from_bytes(data[p+6:p+10], 'big')
    return a, b, c, p + 10

